(function(){
  'use strict';
  const GROUPS=[
    {key:'style',label:'Phong cách',get:o=>o.primaryStyle||o.category},
    {key:'occasion',label:'Dịp mặc',get:o=>o.filters?.occasions||[]},
    {key:'color',label:'Màu chủ đạo',get:o=>o.filters?.color},
    {key:'fit',label:'Hiệu ứng dáng',get:o=>o.filters?.fit||[]},
    {key:'bottom',label:'Quần / váy',get:o=>o.filters?.bottom},
    {key:'footwear',label:'Giày',get:o=>o.filters?.footwear},
    {key:'complexity',label:'Độ cầu kỳ',get:o=>o.filters?.complexity}
  ];
  const ORDER={
    style:['E-Girl','Baddie Streetwear','Dark Feminine','Goth','Punk / Grunge'],
    occasion:['Đi học','Đi cafe','Đi chơi tối','Chụp ảnh'],
    color:['Đen','Xám / Bạc','Trắng / Sáng','Nâu / Be','Đỏ / Hồng','Màu nổi'],
    fit:['Tôn eo','Che hông / đùi','Hack chân dài','Thoải mái','Cân đối'],
    bottom:['Quần','Váy','Short'],
    footwear:['Sneaker','Boots / Platform','Giày khác'],
    complexity:['Tối giản','Cân bằng','Nhiều layer']
  };
  const all=()=>Array.isArray(window.outfits)?window.outfits:(typeof outfits!=='undefined'?outfits:[]);
  const values=(group,data)=>{
    const set=new Set();
    data.forEach(o=>{const v=group.get(o);(Array.isArray(v)?v:[v]).filter(Boolean).forEach(x=>set.add(x));});
    const preferred=ORDER[group.key]||[];
    return [...set].sort((a,b)=>{
      const ai=preferred.indexOf(a),bi=preferred.indexOf(b);
      if(ai>=0||bi>=0)return (ai<0?999:ai)-(bi<0?999:bi);
      return String(a).localeCompare(String(b),'vi');
    });
  };
  const selectedCount=state=>Object.values(state).reduce((n,v)=>n+(v?.size||0),0);
  const matches=(o,state)=>GROUPS.every(g=>{
    const chosen=state[g.key]; if(!chosen||chosen.size===0)return true;
    const raw=g.get(o), arr=Array.isArray(raw)?raw:[raw];
    return arr.some(v=>chosen.has(v));
  });
  function init(root){
    root.classList.add('ac-filter-root');
    const mode=root.dataset.acFilterMode||'static';
    const lockStyle=root.dataset.acFilterLockStyle||'';
    const source=lockStyle?all().filter(o=>(o.primaryStyle||o.category)===lockStyle):all();
    const groups=GROUPS.filter(g=>!(lockStyle&&g.key==='style'));
    const state={}; groups.forEach(g=>state[g.key]=new Set());
    root.innerHTML=`<div class="ac-filter-toolbar"><button class="ac-filter-toggle" type="button" aria-expanded="false">☷ LỌC OUTFIT <span data-filter-badge></span></button><div class="ac-filter-active" aria-live="polite"></div><span class="ac-filter-count"></span></div><div class="ac-filter-panel" role="dialog" aria-modal="false" aria-label="Bộ lọc outfit"><div class="ac-filter-head"><strong class="ac-filter-title">Lọc outfit</strong><button class="ac-filter-close" type="button" aria-label="Đóng bộ lọc">×</button></div><div class="ac-filter-groups"></div><div class="ac-filter-actions"><button class="ac-filter-clear" type="button">Xóa bộ lọc</button><button class="ac-filter-apply" type="button">Xem kết quả</button></div></div>`;
    const mobile=document.createElement('button');
    mobile.type='button'; mobile.className='ac-filter-mobile-trigger'; mobile.innerHTML='☷ LỌC OUTFIT <strong data-mobile-badge></strong>'; mobile.setAttribute('aria-expanded','false');
    root.insertAdjacentElement('afterend',mobile);
    const groupsEl=root.querySelector('.ac-filter-groups');
    groups.forEach(g=>{
      const wrap=document.createElement('fieldset'); wrap.className='ac-filter-group';
      const legend=document.createElement('legend'); legend.className='ac-filter-group-title'; legend.textContent=g.label; wrap.appendChild(legend);
      const opts=document.createElement('div'); opts.className='ac-filter-options';
      values(g,source).forEach(v=>{
        const count=source.filter(o=>{const raw=g.get(o),arr=Array.isArray(raw)?raw:[raw];return arr.includes(v);}).length;
        const b=document.createElement('button'); b.type='button'; b.className='ac-filter-option'; b.textContent=`${v} · ${count}`; b.dataset.group=g.key; b.dataset.value=v; b.setAttribute('aria-pressed','false');
        b.addEventListener('click',()=>{const s=state[g.key];s.has(v)?s.delete(v):s.add(v);sync();}); opts.appendChild(b);
      });
      wrap.appendChild(opts); groupsEl.appendChild(wrap);
    });
    const open=(yes)=>{root.classList.toggle('is-open',yes);root.querySelector('.ac-filter-toggle').setAttribute('aria-expanded',String(yes));mobile.setAttribute('aria-expanded',String(yes));document.documentElement.style.overflow=yes&&matchMedia('(max-width:768px)').matches?'hidden':'';};
    root.querySelector('.ac-filter-toggle').addEventListener('click',()=>open(!root.classList.contains('is-open')));
    mobile.addEventListener('click',()=>open(true));
    root.querySelector('.ac-filter-close').addEventListener('click',()=>open(false));
    root.querySelector('.ac-filter-apply').addEventListener('click',()=>open(false));
    root.querySelector('.ac-filter-clear').addEventListener('click',()=>{Object.values(state).forEach(s=>s.clear());sync();});
    function applyStatic(matched){
      const ids=new Set(matched.map(o=>o.id));
      document.querySelectorAll(root.dataset.acFilterCardSelector||'.mix-card[data-outfit-id]').forEach(card=>{card.hidden=!ids.has(card.dataset.outfitId);});
      document.querySelectorAll('.mix-style-section').forEach(sec=>{
        const cards=[...sec.querySelectorAll('.mix-card[data-outfit-id]')];
        const visible=cards.filter(c=>!c.hidden).length;
        sec.hidden=cards.length>0&&visible===0;
        const count=sec.querySelector('.mix-style-count');if(count)count.textContent=`${visible} LOOKS`;
      });
      let empty=document.querySelector('.ac-filter-static-empty');
      if(!empty){empty=document.createElement('p');empty.className='ac-filter-static-empty';empty.textContent='Không có outfit khớp tất cả bộ lọc. Hãy bỏ bớt một lựa chọn.';root.insertAdjacentElement('afterend',empty);}
      empty.style.display=matched.length?'none':'block';
    }
    function sync(){
      const n=selectedCount(state);
      root.querySelectorAll('.ac-filter-option').forEach(b=>{const on=state[b.dataset.group]?.has(b.dataset.value);b.classList.toggle('is-selected',!!on);b.setAttribute('aria-pressed',String(!!on));});
      const active=root.querySelector('.ac-filter-active');active.innerHTML='';
      groups.forEach(g=>state[g.key].forEach(v=>{const chip=document.createElement('button');chip.type='button';chip.className='ac-filter-chip';chip.textContent=`${v} ×`;chip.addEventListener('click',()=>{state[g.key].delete(v);sync();});active.appendChild(chip);}));
      const matched=source.filter(o=>matches(o,state));
      root.querySelector('.ac-filter-count').textContent=`${matched.length} LOOK PHÙ HỢP`;
      root.querySelector('[data-filter-badge]').textContent=n?`(${n})`:'';
      mobile.querySelector('[data-mobile-badge]').textContent=n?`(${n})`:'';
      const publicState={};Object.entries(state).forEach(([k,v])=>publicState[k]=[...v]);
      if(mode==='home'&&typeof window.acApplyOutfitFilters==='function')window.acApplyOutfitFilters(publicState,matched,n);
      else if(mode==='style'&&typeof window.acApplyStyleOutfitFilters==='function')window.acApplyStyleOutfitFilters(publicState,matched,n);
      else applyStatic(matched);
      if(n&&window.acTrack)window.acTrack('filter_outfits',{filter_count:n,result_count:matched.length,filter_mode:mode});
    }
    root._acFilterSync=sync;
    sync();
  }
  function boot(){document.querySelectorAll('[data-ac-filter-mode]').forEach(init);}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
